				stuck++
				mu.Unlock()
			}
		}()
	}

	// Let the callers fill the channel, then shut down underneath them.
	var shutdownErr string
	shutdownDone := make(chan struct{})
	if shutdown {
		go func() {
			time.Sleep(2 * time.Millisecond)
			if err := r.Shutdown().Error(); err != nil {
				shutdownErr = err.Error()
			}
			close(shutdownDone)
		}()
	} else {
		close(shutdownDone)
	}

	<-shutdownDone

