			ids = append(ids, string(n.id))
		}
	}
	return ids
}

func assuranceMaxTerm(nodes []*assuranceProbeNode) uint64 {
	var maxTerm uint64
	for _, n := range nodes {
		if term := n.raft.getCurrentTerm(); term > maxTerm {
			maxTerm = term
		}
	}
	return maxTerm
}

