	deadline = time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		for _, n := range nodes[:3] {
			if n != leader && n.raft.State() == Leader {
				successor = n
				break
			}
		}
		if successor != nil {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	successorValue := "<no successor>"
	successorTerm := uint64(0)
	if successor != nil {
		successorTerm = successor.raft.getCurrentTerm()
		if err := successor.raft.Apply([]byte("new"), 5*time.Second).Error(); err == nil {
			time.Sleep(100 * time.Millisecond)
			successorValue = assuranceLastValue(successor)
		} else {
			successorValue = "<apply failed>"
		}
	}

	// Give the stalled leader the non-voter's acknowledgement.
	time.Sleep(time.Duration(reconnectAfterMs) * time.Millisecond)
	assuranceConnect(leader, nv)

	verifyDone := make(chan error, 1)
	go func() { verifyDone <- verify.Error() }()
	verifyErr := "pending"
	select {
	case err := <-verifyDone:
		if err == nil {
			verifyErr = "nil"
		} else {
			verifyErr = err.Error()
		}
	case <-time.After(4 * time.Second):
	}

	leaderValue := assuranceLastValue(leader)
	assuranceEmit(t, map[string]interface{}{
		"event":               "assurance_stale_read_result",
		"reconnect_after_ms":  reconnectAfterMs,
		"leader_id":           string(leader.id),
		"verify_error":        verifyErr,
		"leader_value":        leaderValue,
		"successor_value":     successorValue,
		"stale_values_differ": verifyErr == "nil" && leaderValue != successorValue,
		"successor_term":      successorTerm,
		"leader_term_after":   leader.raft.getCurrentTerm(),
		"leader_term_before":  leaderTermBefore,
		"leader_state_after":  leader.raft.State().String(),
		"stalls_triggered":    atomic.LoadInt32(leader.slow.stalls),
		"elapsed_ms":          time.Since(startAt).Milliseconds(),
	})
}

